function header(){const page=document.body.dataset.page||'home';return `<div class="announce"><div class="wrap announce-inner"><span><i></i> Wholesale enquiries open</span><p>Authentic flavour across France since 2003</p><a href="mailto:info@shamafr.com">info@shamafr.com ↗</a></div></div><header class="header"><nav class="nav-shell wrap"><a class="brand brand-studio" href="index.html"><span class="brand-emblem"><b>S</b><i></i></span><span><strong>SHAMA</strong><small>INTERNATIONAL</small></span></a><button class="mobile-toggle" aria-label="Open menu"><i></i><i></i></button><div class="navlinks"><a class="${page==='home'?'active':''}" href="index.html"><span>Home</span></a><a class="${page==='about'?'active':''}" href="about.html"><span>About us</span></a><a class="${page==='catalogue'?'active':''}" href="catalogue.html"><span>Catalogue</span></a><div class="drop"><span class="drop-label">Products <b>⌄</b></span><div class="mega-menu"><div class="mega-head"><span>Explore by range</span><a href="catalogue.html">Full catalogue ↗</a></div><div class="mega-grid">${categories.map((c,i)=>`<a href="${fileMap[c.slug]}"><b>0${i+1}</b><span><strong>${c.name}</strong><small>${c.desc}</small></span><i>↗</i></a>`).join('')}</div><div class="mega-foot"><span>Need help choosing?</span><a href="contact.html">Talk to our team →</a></div></div></div><a class="${page==='contact'?'active':''}" href="contact.html"><span>Contact</span></a></div><a class="header-cta" href="contact.html"><span>Bulk order</span><b>↗</b></a></nav></header>`}
