function renderProducts(main){const css=document.createElement('link');css.rel='stylesheet';css.href='product-runway.css?v=20260721-16';document.head.appendChild(css);const slug=document.body.dataset.category,c=categories.find(x=>x.slug===slug),items=productData.filter(x=>x.category===slug);activeCatalog=items;document.title=`${c.name} | Shama International`;const first=items[0];main.innerHTML=hero(c.name+'.',c.desc+' — explore the complete Shama range.','Products / '+c.name)+`<section class="product-runway section"><div class="wrap runway-top"><div><span class="eyebrow">Shama ${c.name}</span><h2>Choose your<br>next bestseller.</h2></div><div class="runway-search"><label>Search the range<input id="runway-search" type="search" placeholder="Type a product name…"></label><span><b id="runway-count">${items.length}</b> products</span></div></div><div class="wrap runway-layout"><aside class="runway-preview"><div class="runway-stage"><span class="runway-no" id="runway-no">01</span><div class="runway-rings"></div><img id="runway-image" src="${first?.image||''}" alt="${first?.title||c.name}"><span class="runway-shadow"></span><i>SHAMA</i></div><div class="runway-copy"><span class="eyebrow">Selected product</span><h3 id="runway-title">${first?.title||c.name}</h3><p id="runway-pack">${first?.pack||'Contact us for available pack sizes'}</p><div class="runway-assurance"><span>✓ Wholesale supply</span><span>✓ Delivery support</span></div><button class="bulk-buy runway-add" type="button" data-product="${(first?.title||'').replace(/"/g,'&quot;')}" data-pack="${(first?.pack||'').replace(/"/g,'&quot;')}"><span>Add to bulk order</span><b>↗</b></button></div></aside><div class="runway-list-wrap"><div class="runway-list-head"><span>Product index</span><span>Pack details</span></div><div id="runway-list" class="runway-list"></div></div></div></section>`;const list=document.querySelector('#runway-list'),search=document.querySelector('#runway-search');let shown=items;function selectItem(x,i,row){document.querySelectorAll('.runway-row').forEach(r=>r.classList.toggle('active',r===row));const img=document.querySelector('#runway-image');img.classList.remove('switch');void img.offsetWidth;img.src=x.image;img.alt=x.title;img.classList.add('switch');document.querySelector('#runway-no').textContent=String(i+1).padStart(2,'0');document.querySelector('#runway-title').textContent=x.title;document.querySelector('#runway-pack').textContent=x.pack||'Contact us for available pack sizes';const add=document.querySelector('.runway-add');add.dataset.product=x.title;add.dataset.pack=x.pack||''}function drawRows(){list.innerHTML=shown.map((x,i)=>`<button type="button" class="runway-row ${i===0?'active':''}" data-runway="${i}"><b>${String(i+1).padStart(2,'0')}</b><span><strong>${x.title}</strong><small>${x.pack||'Pack sizes available'}</small></span><i>→</i></button>`).join('')||'<div class="runway-empty">No matching products found.</div>';document.querySelector('#runway-count').textContent=shown.length;if(shown[0])selectItem(shown[0],0,list.querySelector('.runway-row'))}list.addEventListener('mouseover',e=>{const row=e.target.closest('.runway-row');if(row)selectItem(shown[+row.dataset.runway],+row.dataset.runway,row)});list.addEventListener('click',e=>{const row=e.target.closest('.runway-row');if(row)selectItem(shown[+row.dataset.runway],+row.dataset.runway,row)});search.oninput=()=>{const term=search.value.toLowerCase();shown=items.filter(x=>x.title.toLowerCase().includes(term)||(x.pack||'').toLowerCase().includes(term));drawRows()};drawRows()}
function drawProducts(items){document.querySelector('#product-grid').innerHTML=items.length?items.map(x=>`<article class="product-card"><div class="product-image"><img loading="lazy" src="${x.image}" alt="${x.title}"></div><div class="product-body"><span class="eyebrow">Shama</span><h3>${x.title}</h3><p>${x.pack||'Available in selected pack sizes'}</p><button class="bulk-buy" type="button" data-product="${x.title.replace(/"/g,'&quot;')}" data-pack="${(x.pack||'').replace(/"/g,'&quot;')}"><span>Buy in bulk</span><b>↗</b></button></div></article>`).join(''):`<p class="lead">Products are being prepared for this category. Please contact us for the current range.</p>`}
