const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');revealObserver.unobserve(entry.target)}}),{threshold:.1,rootMargin:'0px 0px -40px'});
document.querySelectorAll('section .section-head,section .split,.category-card,.product-card,.product-showcase,.steps-grid article,.wholesale-head,.values-card,.pillar,.about-grid,.founder-grid,.manifesto-grid,.journey-line article,.founder-editorial-grid,.belief-strips article,.vision-inner,.catalogue-layout,.catalogue-note .wrap,.trade-layout,.location-grid,.contact-grid,.cta-box').forEach(el=>{el.classList.add('reveal-on-scroll');revealObserver.observe(el)});
window.addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;document.documentElement.style.setProperty('--scroll',`${max?scrollY/max*100:0}%`)},{passive:true});
document.addEventListener('pointermove',e=>{const card=e.target.closest('.product-card');if(!card||innerWidth<901)return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(900px) rotateX(${-y*4}deg) rotateY(${x*5}deg) translateY(-5px)`});
document.addEventListener('pointerout',e=>{const card=e.target.closest('.product-card');if(card)card.style.transform=''});

const bulkModal=`<div class="bulk-modal" id="bulk-modal" aria-hidden="true"><div class="bulk-backdrop" data-close-bulk></div><section class="bulk-dialog" role="dialog" aria-modal="true" aria-labelledby="bulk-title"><button class="bulk-close" type="button" data-close-bulk aria-label="Close">×</button><div class="bulk-intro"><span class="eyebrow">Wholesale enquiry</span><h2 id="bulk-title">Order in bulk</h2><p>Tell us what you need. Send the prepared enquiry directly by email or WhatsApp.</p></div><form id="bulk-form" class="bulk-form"><div class="selected-product"><small>Selected product</small><strong id="bulk-product"></strong><span id="bulk-pack"></span></div><label>Quantity / cases<input name="quantity" type="number" min="1" value="10" required></label><label>Business name<input name="business" placeholder="Your shop or company"></label><label>Your name<input name="name" required placeholder="Full name"></label><label>Phone / WhatsApp<input name="phone" type="tel" required placeholder="+33 …"></label><label class="bulk-full">Delivery city / postcode<input name="location" required placeholder="Paris 75001"></label><label class="bulk-full">Additional details<textarea name="notes" placeholder="Preferred pack size, delivery date, etc."></textarea></label><div class="bulk-actions bulk-full"><button class="send-email" type="button">✉ <span>Send by email</span></button><button class="send-whatsapp" type="button">◉ <span>Send on WhatsApp</span></button></div><small class="bulk-note bulk-full">This opens your email or WhatsApp app with the complete enquiry ready to send.</small></form></section></div>`;
document.body.insertAdjacentHTML('beforeend',bulkModal);
const bulk=document.querySelector('#bulk-modal'),bulkForm=document.querySelector('#bulk-form');
function closeBulk(){bulk.classList.remove('open');bulk.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}
document.addEventListener('click',e=>{const trigger=e.target.closest('.bulk-buy');if(trigger){document.querySelector('#bulk-product').textContent=trigger.dataset.product;document.querySelector('#bulk-pack').textContent=trigger.dataset.pack;bulk.classList.add('open');bulk.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')}if(e.target.closest('[data-close-bulk]'))closeBulk()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeBulk()});
function enquiryText(){if(!bulkForm.reportValidity())return null;const data=new FormData(bulkForm),product=document.querySelector('#bulk-product').textContent,pack=document.querySelector('#bulk-pack').textContent;return `Hello Shama International,\n\nI would like a bulk quotation.\n\nProduct: ${product}\nPack details: ${pack||'Please advise'}\nQuantity / cases: ${data.get('quantity')}\nBusiness: ${data.get('business')||'Not provided'}\nName: ${data.get('name')}\nPhone: ${data.get('phone')}\nDelivery location: ${data.get('location')}\nAdditional details: ${data.get('notes')||'None'}\n\nPlease share price, MOQ and delivery availability.`}
document.querySelector('.send-email').addEventListener('click',()=>{const text=enquiryText();if(text)location.href=`mailto:info@shamafr.com?subject=${encodeURIComponent('Bulk order enquiry — '+document.querySelector('#bulk-product').textContent)}&body=${encodeURIComponent(text)}`});
document.querySelector('.send-whatsapp').addEventListener('click',()=>{const text=enquiryText();if(text)window.open(`https://wa.me/33143420579?text=${encodeURIComponent(text)}`,'_blank','noopener')});

let bulkCart=[];try{bulkCart=JSON.parse(localStorage.getItem('shamaBulkOrder')||'[]')}catch(_){bulkCart=[]}
const cartUI=`<button class="order-tray" type="button"><span class="tray-icon">▤</span><span><small>Bulk order</small><b><i id="order-count">0</i> products selected</b></span><em>↑</em></button><div class="order-drawer" aria-hidden="true"><div class="order-shade" data-cart-close></div><aside><div class="drawer-head"><div><span class="eyebrow">Build one enquiry</span><h2>Your bulk order</h2></div><button type="button" data-cart-close>×</button></div><p class="drawer-intro">Add products from any category, set cases, then send everything together.</p><div id="cart-items" class="cart-items"></div><div class="cart-empty" id="cart-empty"><span>＋</span><h3>Your list is empty</h3><p>Browse products and choose “Add to bulk order”.</p><a href="catalogue.html">Explore catalogue →</a></div><form id="cart-customer" class="cart-customer"><label>Business<input name="business" required placeholder="Shop / company"></label><label>Your name<input name="name" required placeholder="Full name"></label><label>Phone<input name="phone" required placeholder="+33 …"></label><label>Delivery location<input name="location" required placeholder="City / postcode"></label><label class="cart-wide">Notes<textarea name="notes" placeholder="Delivery timing or other requirements"></textarea></label></form><div class="cart-send"><button class="cart-email" type="button">✉ Email complete list</button><button class="cart-wa" type="button">◉ WhatsApp complete list</button></div></aside></div>`;document.body.insertAdjacentHTML('beforeend',cartUI);
const drawer=document.querySelector('.order-drawer');function saveCart(){try{localStorage.setItem('shamaBulkOrder',JSON.stringify(bulkCart))}catch(_){}renderBulkCart()}
function renderBulkCart(){const items=document.querySelector('#cart-items'),empty=document.querySelector('#cart-empty'),count=document.querySelector('#order-count');count.textContent=bulkCart.length;items.innerHTML=bulkCart.map((x,i)=>`<article class="cart-item"><div><strong>${x.product}</strong><small>${x.pack||'Pack size to be confirmed'}</small></div><div class="cart-qty"><button type="button" data-cart-minus="${i}">−</button><span>${x.qty} cases</span><button type="button" data-cart-plus="${i}">+</button></div><button class="cart-remove" type="button" data-cart-remove="${i}">×</button></article>`).join('');empty.hidden=bulkCart.length>0;items.hidden=!bulkCart.length;document.querySelector('.cart-customer').hidden=!bulkCart.length;document.querySelector('.cart-send').hidden=!bulkCart.length;const productField=document.querySelector('#trade-form [name="products"]');if(productField){productField.value=bulkCart.map(x=>`${x.product} — ${x.qty} cases`).join('; ');const q=document.querySelector('#trade-form [name="quantity"]');if(q)q.value=bulkCart.reduce((n,x)=>n+x.qty,0)||1;const c=document.querySelector('#trade-form [name="category"]');if(c)c.value=bulkCart.length?'Multiple categories':''}renderTradePickerSelected()}
function openCart(){drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')}
function closeCart(){drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}
function addCartProduct(product,pack){const found=bulkCart.find(x=>x.product===product&&x.pack===pack);if(found)found.qty+=10;else bulkCart.push({product,pack,qty:10});saveCart();if(document.body.dataset.page!=='contact')openCart()}
document.addEventListener('click',e=>{const add=e.target.closest('.bulk-buy');if(add){e.preventDefault();e.stopPropagation();addCartProduct(add.dataset.product,add.dataset.pack||'');return}if(e.target.closest('.order-tray'))openCart();if(e.target.closest('[data-cart-close]'))closeCart();const plus=e.target.closest('[data-cart-plus]'),minus=e.target.closest('[data-cart-minus]'),remove=e.target.closest('[data-cart-remove]');if(plus){bulkCart[+plus.dataset.cartPlus].qty++;saveCart()}if(minus){const x=bulkCart[+minus.dataset.cartMinus];x.qty=Math.max(1,x.qty-1);saveCart()}if(remove){bulkCart.splice(+remove.dataset.cartRemove,1);saveCart()}},true);
function cartMessage(){if(!bulkCart.length)return null;const form=document.querySelector('#cart-customer');if(!form.reportValidity())return null;const d=new FormData(form),lines=bulkCart.map((x,i)=>`${i+1}. ${x.product}\n   Pack: ${x.pack||'Please advise'}\n   Quantity: ${x.qty} cases`).join('\n\n');return `Hello Shama International,\n\nPlease provide one wholesale quotation for the following products:\n\n${lines}\n\nBusiness: ${d.get('business')}\nName: ${d.get('name')}\nPhone: ${d.get('phone')}\nDelivery: ${d.get('location')}\nNotes: ${d.get('notes')||'None'}\n\nPlease confirm availability, MOQ, pricing and delivery.`}
document.querySelector('.cart-email').onclick=()=>{const t=cartMessage();if(t)location.href=`mailto:info@shamafr.com?subject=${encodeURIComponent('Multi-product wholesale enquiry')}&body=${encodeURIComponent(t)}`};document.querySelector('.cart-wa').onclick=()=>{const t=cartMessage();if(t)window.open(`https://wa.me/33143420579?text=${encodeURIComponent(t)}`,'_blank','noopener')};
function labelBulkButtons(){document.querySelectorAll('.bulk-buy span').forEach(x=>{if(x.textContent!=='Add to bulk order')x.textContent='Add to bulk order'})}labelBulkButtons();new MutationObserver(labelBulkButtons).observe(document.body,{childList:true,subtree:true});renderBulkCart();
function renderTradePickerSelected(){const box=document.querySelector('#trade-selected');if(!box)return;box.innerHTML=bulkCart.length?bulkCart.map((x,i)=>`<article><div><b>${i+1}</b><span><strong>${x.product}</strong><small>${x.pack||'Pack size to be confirmed'}</small></span></div><div class="picker-qty"><button type="button" data-cart-minus="${i}">−</button><em>${x.qty} cases</em><button type="button" data-cart-plus="${i}">+</button><button type="button" data-cart-remove="${i}">×</button></div></article>`).join(''):`<div class="picker-empty"><span>＋</span><p>No products selected yet. Add as many as you need below.</p></div>`;const total=document.querySelector('#picker-total');if(total)total.textContent=`${bulkCart.length} products · ${bulkCart.reduce((n,x)=>n+x.qty,0)} cases`}
if(document.body.dataset.page==='contact'){const trade=document.querySelector('#trade-form'),categoryLabel=trade.querySelector('[name="category"]').closest('label'),quantityLabel=trade.querySelector('[name="quantity"]').closest('label'),productsLabel=trade.querySelector('[name="products"]').closest('label');categoryLabel.hidden=true;quantityLabel.hidden=true;productsLabel.hidden=true;trade.insertAdjacentHTML('afterbegin',`<section class="trade-picker trade-full"><div class="picker-head"><div><span class="eyebrow">Step 1 · Build your list</span><h3>Choose multiple products</h3><p>Select products across any category. You only send one final enquiry.</p></div><b id="picker-total">0 products · 0 cases</b></div><div id="trade-selected" class="trade-selected"></div><div class="picker-tools"><input id="picker-search" type="search" placeholder="Search rice, spices, sauces…"><select id="picker-category"><option value="">All categories</option>${categories.map(c=>`<option value="${c.slug}">${c.name}</option>`).join('')}</select></div><div id="picker-results" class="picker-results"></div></section>`);const results=document.querySelector('#picker-results'),search=document.querySelector('#picker-search'),filter=document.querySelector('#picker-category');function drawPicker(){const term=search.value.toLowerCase(),cat=filter.value,list=productData.filter(x=>(!cat||x.category===cat)&&(!term||x.title.toLowerCase().includes(term))).slice(0,12);results.innerHTML=list.map(x=>`<article><div><strong>${x.title}</strong><small>${x.pack||'Pack sizes available'}</small></div><button type="button" data-picker-product="${x.title.replace(/"/g,'&quot;')}" data-picker-pack="${(x.pack||'').replace(/"/g,'&quot;')}">＋ Add</button></article>`).join('')||'<p class="picker-no-result">No matching products found.</p>'}search.oninput=drawPicker;filter.onchange=drawPicker;results.onclick=e=>{const add=e.target.closest('[data-picker-product]');if(add)addCartProduct(add.dataset.pickerProduct,add.dataset.pickerPack||'')};drawPicker();renderBulkCart();function combinedTradeText(){if(!bulkCart.length){document.querySelector('.trade-picker').classList.add('picker-alert');document.querySelector('.trade-picker').scrollIntoView({behavior:'smooth',block:'center'});return null}if(!trade.reportValidity())return null;const d=new FormData(trade),lines=bulkCart.map((x,i)=>`${i+1}. ${x.product}\n   Pack: ${x.pack||'Please advise'}\n   Quantity: ${x.qty} cases`).join('\n\n');return `Hello Shama International,\n\nPlease provide one wholesale quotation for all products below:\n\n${lines}\n\nBusiness: ${d.get('business')}\nContact: ${d.get('name')}\nEmail: ${d.get('email')}\nPhone: ${d.get('phone')}\nDelivery: ${d.get('city')} ${d.get('postcode')}\nNotes: ${d.get('notes')||'None'}\n\nPlease confirm availability, MOQ, pricing and delivery options.`}document.querySelector('.trade-email').onclick=()=>{const t=combinedTradeText();if(t)location.href=`mailto:info@shamafr.com?subject=${encodeURIComponent('Multi-product wholesale enquiry')}&body=${encodeURIComponent(t)}`};document.querySelector('.trade-whatsapp').onclick=()=>{const t=combinedTradeText();if(t)window.open(`https://wa.me/33143420579?text=${encodeURIComponent(t)}`,'_blank','noopener')}}
if(document.body.dataset.page==='product'){const zoomCss=document.createElement('link');zoomCss.rel='stylesheet';zoomCss.href='product-zoom.css?v=20260721-17';document.head.appendChild(zoomCss);document.body.insertAdjacentHTML('beforeend',`<div class="product-lightbox" id="product-lightbox" aria-hidden="true"><div class="zoom-backdrop" data-zoom-close></div><button class="zoom-close" type="button" data-zoom-close aria-label="Close image">×</button><div class="zoom-dialog"><div class="zoom-image-stage"><span>Click outside to close</span><img id="zoom-image" alt=""></div><div class="zoom-info"><span class="eyebrow">Shama product</span><h2 id="zoom-title"></h2><p id="zoom-pack"></p></div></div></div>`)}
document.addEventListener('click',e=>{const image=e.target.closest('#runway-image');if(image){const box=document.querySelector('#product-lightbox');document.querySelector('#zoom-image').src=image.src;document.querySelector('#zoom-image').alt=image.alt;document.querySelector('#zoom-title').textContent=document.querySelector('#runway-title').textContent;document.querySelector('#zoom-pack').textContent=document.querySelector('#runway-pack').textContent;box.classList.add('open');box.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')}if(e.target.closest('[data-zoom-close]')){const box=document.querySelector('#product-lightbox');if(box){box.classList.remove('open');box.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const box=document.querySelector('#product-lightbox');if(box?.classList.contains('open')){box.classList.remove('open');document.body.classList.remove('modal-open')}}});
